const at = (a: number[], f: number): number =>
  a[Math.max(0, Math.min(a.length - 1, Math.round(f)))] ?? 0;

/** Mouth openness at a global frame. Clamped at both ends. */
export const openAt = (f: number): number => at(MOUTH, f);

/** Lip spread at a global frame. */
export const spreadAt = (f: number): number => at(SPREAD, f);

/** Onset strength at a global frame. */
export const accentAt = (f: number): number => at(ACCENT, f);
